        for (const Registro& registro : grupo.registros) {
            aceptados += registro.recuento.aceptados;
            rechazados += registro.recuento.rechazados;
        }
    }
    bool verificado = mismos_datos(actual, recuperado);
    std::cout << "Entrée acceptée\nGroupes : " << actual.grupos.size()
              << "\nAcceptés : " << aceptados
              << "\nRejetés : " << rechazados
              << "\nVérification : " << verificado;
