    std::getline(lectura_escritura, texto_escritura);
    if (lectura_escritura.bad() || !lectura_escritura.eof()) {
        std::cout << "Erreur de vérification du test d’écriture";
        return 1;
    }
    std::cout << "Écriture : " << fallo_escritura
              << ";Vide : " << texto_escritura.empty() << '\n';

    std::ofstream cierre{"ensayo_cierre.txt"};
    if (!cierre) { std::cout << "Erreur d’ouverture du test de fermeture"; return 1; }
    cierre << "ESSAI";
    if (!cierre) { std::cout << "Erreur d’écriture du test de fermeture"; return 1; }
    cierre.close();
    if (!cierre) { std::cout << "Erreur de première fermeture"; return 1; }
    cierre.close();
    const bool fallo_cierre = !cierre;

    std::ifstream lectura_cierre{"ensayo_cierre.txt"};
    if (!lectura_cierre) { std::cout << "Erreur de lecture du test de fermeture"; return 1; }
    std::string texto_cierre;
    if (!std::getline(lectura_cierre, texto_cierre)) {
        std::cout << "Erreur de récupération du texte";
        return 1;
    }
    lectura_cierre >> std::ws;
    if (lectura_cierre.bad() || !lectura_cierre.eof()) {
        std::cout << "Erreur de vérification de fermeture";
        return 1;
    }
    std::cout << "Fermeture : " << fallo_cierre
              << ";Conservé : " << (texto_cierre == "ESSAI");
    return 0;
}

