std::ostream& operator<<(std::ostream& destino, const Recuento& valor) {
    return destino << '[' << valor.aceptados << ';' << valor.rechazados << ']';
}

std::istream& operator>>(std::istream& origen, Recuento& destino) {
    char abre{0};
    char separador{0};
    char cierra{0};
    int aceptados{0};
    int rechazados{0};
    if (!(origen >> abre >> aceptados >> separador >> rechazados >> cierra)) {
        return origen;
    }
    Recuento candidato{aceptados, rechazados};
    if (abre != '[' || separador != ';' || cierra != ']'
        || !recuento_valido(candidato)) {
        origen.setstate(std::ios::failbit);
        return origen;
    }
    destino = candidato;
    return origen;
}

struct Registro {
    int id;
    Recuento recuento;
};

struct Grupo {
    int id;
    std::vector<Registro> registros;
};

bool contiene_registro(const Grupo& grupo, int id) {
    for (const Registro& registro : grupo.registros) {
        if (registro.id == id) { return true; }
    }
    return false;
}

bool leer_grupo(std::istream& entrada, Grupo& destino) {
    char abre{0};
    std::string etiqueta;
    std::string nombre;
    if (!(entrada >> abre >> etiqueta >> nombre)
        || abre != '{' || etiqueta != "groupe") {
        return false;
    }
    int id{-1};
    if (!buscar_grupo(nombre, id)) { return false; }
    Grupo candidato{id, {}};
    while (true) {
        entrada >> std::ws;
        if (!entrada || entrada.eof()) { return false; }
        if (entrada.peek() == '}') {
            entrada.get();
            if (!entrada) { return false; }
            destino = candidato;
            return true;
        }
        Registro registro{0, {0, 0}};
        if (!(entrada >> registro.id >> registro.recuento)
            || registro.id < 0 || registro.id > 9
            || contiene_registro(candidato, registro.id)) {
            return false;
        }
        candidato.registros.push_back(registro);
    }
}

struct Conjunto {
    std::vector<Grupo> grupos;
};

bool contiene_grupo(const Conjunto& conjunto, int id) {
    for (const Grupo& grupo : conjunto.grupos) {
        if (grupo.id == id) { return true; }
    }
    return false;
}

bool leer_conjunto(std::istream& entrada, Conjunto& destino) {
    char abre{0};
    std::string etiqueta;
    if (!(entrada >> abre >> etiqueta)
        || abre != '{' || etiqueta != "ensemble") {
        return false;
    }
    Conjunto candidato{};
    while (true) {
        entrada >> std::ws;
        if (!entrada || entrada.eof()) { return false; }
        if (entrada.peek() == '}') {
            entrada.get();
            if (!entrada) { return false; }
            destino = candidato;
            return true;
        }
        Grupo grupo{0, {}};
        if (!leer_grupo(entrada, grupo)
            || contiene_grupo(candidato, grupo.id)) {
            return false;
        }
        candidato.grupos.push_back(grupo);
    }
}

bool leer_muestra_completa(std::istream& entrada, Conjunto& destino) {
    Conjunto candidato{};
    if (!leer_conjunto(entrada, candidato)) { return false; }
    entrada >> std::ws;
    if (entrada.bad() || !entrada.eof()) { return false; }
    destino = candidato;
    return true;
}

bool grupo_valido(const Grupo& grupo) {
    if (grupo.id < 0 || grupo.id >= 3 || grupo.registros.size() > 10) {
        return false;
    }
    for (const Registro& registro : grupo.registros) {
        if (registro.id < 0 || registro.id > 9
            || !recuento_valido(registro.recuento)) {
            return false;
        }
        int coincidencias{0};
        for (const Registro& otro : grupo.registros) {
            if (otro.id == registro.id) { ++coincidencias; }
        }
        if (coincidencias != 1) { return false; }
    }
    return true;
}

bool conjunto_valido(const Conjunto& conjunto) {
    if (conjunto.grupos.size() > 3) { return false; }
    for (const Grupo& grupo : conjunto.grupos) {
        if (!grupo_valido(grupo)) { return false; }
        int coincidencias{0};
        for (const Grupo& otro : conjunto.grupos) {
            if (otro.id == grupo.id) { ++coincidencias; }
        }
        if (coincidencias != 1) { return false; }
    }
    return true;
}

bool componer_conjunto(const Conjunto& conjunto, std::string& destino) {
    if (!conjunto_valido(conjunto)) { return false; }
    std::ostringstream salida;
    salida << "{ ensemble";
    for (const Grupo& grupo : conjunto.grupos) {
        std::string nombre;
        if (!nombre_grupo(grupo.id, nombre)) { return false; }
        salida << " { groupe " << nombre;
        for (const Registro& registro : grupo.registros) {
            salida << ' ' << registro.id << registro.recuento;
        }
        salida << " }";
    }
    salida << " }";
    if (!salida) { return false; }
    destino = salida.str();
    return true;
}

bool mismos_datos(const Conjunto& primero, const Conjunto& segundo) {
    if (!conjunto_valido(primero) || !conjunto_valido(segundo)
        || primero.grupos.size() != segundo.grupos.size()) {
        return false;
    }
    const int cantidad_grupos = static_cast<int>(primero.grupos.size());
    for (int i = 0; i < cantidad_grupos; ++i) {
        const Grupo& a = primero.grupos.at(i);
        const Grupo& b = segundo.grupos.at(i);
        if (a.id != b.id || a.registros.size() != b.registros.size()) {
            return false;
        }
        const int cantidad_registros = static_cast<int>(a.registros.size());
        for (int j = 0; j < cantidad_registros; ++j) {
            const Registro& x = a.registros.at(j);
            const Registro& y = b.registros.at(j);
            if (x.id != y.id || x.recuento.aceptados != y.recuento.aceptados
                || x.recuento.rechazados != y.recuento.rechazados) {
                return false;
            }
        }
    }
    return true;
}

// L’ensemble reçu est valide. Le rapport ne le modifie pas.
struct Informe_mayor {
    bool hay_grupo;
    int id;
    int aceptados;
};

Informe_mayor seleccionar_mayor(const Conjunto& conjunto) {
    Informe_mayor mejor{false, -1, 0};
    for (const Grupo& grupo : conjunto.grupos) {
        int total{0};
        for (const Registro& registro : grupo.registros) {
            total += registro.recuento.aceptados;
        }
        if (!mejor.hay_grupo || total > mejor.aceptados) {
            mejor = Informe_mayor{true, grupo.id, total};
        }
    }
    return mejor;
}

int main() {
    const std::string texto_entrada{
        "{ ensemble { groupe bleu } { groupe rouge 2[0;4] } { groupe vert 9[0;0] } }"};
    std::ofstream muestra{"inspecciones_entrada.txt"};
    if (!muestra) { std::cout << "Erreur d’ouverture de l’échantillon"; return 1; }
    muestra << texto_entrada;
    if (!muestra) { std::cout << "Erreur d’écriture de l’échantillon"; return 1; }
    muestra.close();
    if (!muestra) { std::cout << "Erreur de fermeture de l’échantillon"; return 1; }

    const Conjunto previo{{Grupo{1, {{9, {6, 2}}}}}};
    Conjunto actual = previo;
    bool aceptado = false;
    {
        std::ifstream entrada{"inspecciones_entrada.txt"};
        if (!entrada) { std::cout << "Erreur d’ouverture de l’entrée"; return 1; }
        aceptado = leer_muestra_completa(entrada, actual);
        if (entrada.bad()) { std::cout << "Défaillance de lecture"; return 1; }
    }
    if (!aceptado) {
        std::cout << "Entrée rejetée\nÉtat conservé : "
                  << mismos_datos(previo, actual);
        return 0;
    }

    std::string texto_salida;
    if (!componer_conjunto(actual, texto_salida)) {
        std::cout << "Erreur de composition des données";
        return 1;
    }
    std::ofstream guardado{"inspecciones_salida.txt"};
    if (!guardado) { std::cout << "Erreur d’ouverture de sortie"; return 1; }
    guardado << texto_salida;
    if (!guardado) { std::cout << "Erreur d’écriture de sortie"; return 1; }
    guardado.close();
    if (!guardado) { std::cout << "Erreur de fermeture de sortie"; return 1; }

    Conjunto recuperado{};
    {
        std::ifstream comprobacion{"inspecciones_salida.txt"};
        if (!comprobacion) { std::cout << "Erreur de réouverture de sortie"; return 1; }
        if (!leer_muestra_completa(comprobacion, recuperado)
            || comprobacion.bad()) {
            std::cout << "Erreur de relecture de sortie";
            return 1;
        }
    }
    const Conjunto antes_del_informe = actual;
    std::string texto_antes;
    if (!componer_conjunto(actual, texto_antes)) {
        std::cout << "Erreur de composition avant le rapport";
        return 1;
    }

    const Informe_mayor informe = seleccionar_mayor(actual);
    std::string nombre;
    if (informe.hay_grupo && !nombre_grupo(informe.id, nombre)) {
        std::cout << "Erreur d’identification du groupe du rapport";
        return 1;
    }

    std::string texto_despues;
    if (!componer_conjunto(actual, texto_despues)) {
        std::cout << "Erreur de composition après le rapport";
        return 1;
    }
    const bool conservado = mismos_datos(antes_del_informe, actual)
        && texto_antes == texto_despues;
    const bool verificado = mismos_datos(actual, recuperado);
    std::cout << "Entrée acceptée\nGroupes : " << actual.grupos.size();
    if (informe.hay_grupo) {
        std::cout << "\nMeilleur groupe : " << nombre
                  << "\nAcceptés du groupe : " << informe.aceptados;
    } else {
        std::cout << "\nMeilleur groupe : aucun\nAcceptés du groupe : 0";
    }
    std::cout << "\nDonnées conservées : " << conservado
              << "\nVérification : " << verificado;
    if (!conservado || !verificado) { return 1; }
    return 0;
}
